#!/usr/bin/env python3
"""Build the SCHOMBURG application guides (one page, three flavours) from src/:
   src/head.html             the hosted page's head fragment (title, Google Fonts link)
   src/standalone-head.html  the full head of the standalone file (doctype … up to <style>)
   src/style.css + src/koeln/isle.css   the site's stylesheet and the Köln game's stylesheet
   src/body.html, src/boot.js (theme bootstrap), src/logo-data.js (var LOGO=…), src/app.js (the site), src/de.js (the German dictionaries,
   generated by i18n/assemble.py), src/hsaudio.js + src/hsim.js (the hands-on simulators), src/koeln/* (the Köln game, assembled by game/tools)
   fonts/*.ttf               Jost 400/700, Noto Sans TC 400/700 (subsets; SIL OFL 1.1)
   Outputs (dist/):
     index.html                       the page for a web server or GitHub Pages: fonts and libraries as files next to it (dist/fonts, dist/lib)
     test.html                        the same page (the QA harness loads it from a local server)
     aquafin-p4-guide.artifact.html   the hosted-artifact flavour (fonts as files, libraries from a CDN; publish with the font files)
     aquafin-p4-injection-guide.html  the standalone file: fonts embedded (Noto gzipped), libraries from a CDN — one file to send
   The libraries (three.js, pdfmake, docx) come from node_modules (npm ci); without them index.html falls back to the CDN copies."""
import json, base64, gzip, pathlib, shutil
R = pathlib.Path(__file__).parent; src = R / 'src'; dist = R / 'dist'; fonts = R / 'fonts'
rd = lambda p: p.read_text(encoding='utf-8')
head, shead, style, body, boot, logo, app, hsim, hsaudio = [rd(src / f) for f in ['head.html', 'standalone-head.html', 'style.css', 'body.html', 'boot.js', 'logo-data.js', 'app.js', 'hsim.js', 'hsaudio.js']]
style = style + '\n' + rd(src / 'koeln' / 'isle.css')  # the Köln game's stylesheet (V61; the reference ISLE's look in SCHOMBURG red)
de = rd(src / 'de.js') if (src / 'de.js').exists() else ''
assert app.count('(function boot() {') == 1
app = app.replace('(function boot() {', de + '\n(function boot() {', 1)  # the German dictionaries (src/de.js, generated from i18n/de) join the others before the page boots
# V61: SCHOMBURG · KÖLN — the game of the guide in one city (Köln), on the reference ISLE engine (src/koeln, assembled by game/tools)
KOELN = ['lib/SimAudio.js', 'lib/KIT.js', 'lib/LUNA.js', 'lib/PROPS.js', 'lib/DOG.js', 'lib/MAX.js', 'lib/BOSSM.js', 'lib/TOKYO3D.js', 'lib/TPE3D.js', 'lib/SKY.js', 'kw.js', 'koeln3d.js', 'isle/k_stubs.js', 'score85.js', 'kisle.js']
game = '\n'.join(rd(src / 'koeln' / f) for f in KOELN)
app = app.replace("typeof JIB !== 'undefined') JIB.relabel()", "typeof ISLE !== 'undefined') ISLE.relabel()").replace("typeof JIB !== 'undefined') { try { JIB.boot()", "typeof ISLE !== 'undefined') { try { ISLE.boot()")  # Jobsite in Between (V58): core/i18n/input, sky+terrain, actors, audio, UI, world, main — before the site, after the simulators
app = hsaudio + '\n' + hsim + '\n' + game + '\n' + app  # the jobsite sound (src/hsaudio.js), then the hands-on simulators (src/hsim.js), before the site runs its init  # the hands-on simulators (src/hsim.js) are defined before the site runs its init (the guides' shells insert the gates)
THREE_CDN = '<script src="https://cdn.jsdelivr.net/npm/three@0.147.0/build/three.min.js"></script>'
LIBS_CDN = {"pdfmake": ["https://cdn.jsdelivr.net/npm/pdfmake@0.3.11/build/pdfmake.min.js", "https://unpkg.com/pdfmake@0.3.11/build/pdfmake.min.js"], "docx": ["https://cdn.jsdelivr.net/npm/docx@9.11.0/dist/index.iife.js", "https://unpkg.com/docx@9.11.0/dist/index.iife.js"]}
LIBS_LOCAL = {"pdfmake": ["lib/pdfmake.min.js"], "docx": ["lib/docx.iife.js"]}
NAMES = {'jost400': 'jost-400.ttf', 'jost700': 'jost-700.ttf', 'noto400': 'noto-tc-400.ttf', 'noto700': 'noto-tc-700.ttf'}
def fonts_rel(): return json.dumps({k: 'fonts/' + v for k, v in NAMES.items()})
def fonts_embedded():
    o = {}
    for k, v in NAMES.items():
        data = (fonts / v).read_bytes()
        if k.startswith('noto'): o[k] = {"url": "data:application/gzip;base64," + base64.b64encode(gzip.compress(data, 9, mtime=0)).decode(), "gz": True}
        else: o[k] = "data:font/ttf;base64," + base64.b64encode(data).decode()
    return json.dumps(o)
def script(libs, fontsjs): return '<script>' + logo + 'var DOCGEN_LIBS=' + json.dumps(libs) + ';var DOCGEN_FONTS=' + fontsjs + ';\n' + app + '</script>'
def page(prefix, three, libs, fontsjs, full=False): return prefix + '<style>' + style + ('</style>\n</head>\n<body>\n<script>' if full else '</style>\n<script>') + boot + '</script>' + body + three + '\n' + script(libs, fontsjs) + '\n\n</body></html>'
dist.mkdir(exist_ok=True); (dist / 'fonts').mkdir(exist_ok=True)
for v in NAMES.values(): shutil.copy(fonts / v, dist / 'fonts' / v)
art = page(head, THREE_CDN, LIBS_CDN, fonts_rel()); (dist / 'aquafin-p4-guide.artifact.html').write_text(art, encoding='utf-8')
sa = page(shead, THREE_CDN, LIBS_CDN, fonts_embedded(), True); (dist / 'aquafin-p4-injection-guide.html').write_text(sa, encoding='utf-8')
# the libraries as files next to the page (from node_modules, when installed): dist/lib/three.min.js, pdfmake.min.js, docx.iife.js
NM = R / 'node_modules'; (dist / 'lib').mkdir(exist_ok=True)
for src_, dst_ in [('three/build/three.min.js', 'three.min.js'), ('pdfmake/build/pdfmake.min.js', 'pdfmake.min.js'), ('docx/dist/index.iife.js', 'docx.iife.js')]:
    if (NM / src_).exists(): shutil.copy(NM / src_, dist / 'lib' / dst_)
local_ok = all((dist / 'lib' / f).exists() for f in ['three.min.js', 'pdfmake.min.js', 'docx.iife.js'])
three_local = '<script src="lib/three.min.js"></script>' if local_ok else THREE_CDN
libs = LIBS_LOCAL if local_ok else LIBS_CDN
ix = page(shead, three_local, libs, fonts_rel(), True); (dist / 'index.html').write_text(ix, encoding='utf-8'); (dist / 'test.html').write_text(ix, encoding='utf-8')
for f in ['index.html', 'aquafin-p4-guide.artifact.html', 'aquafin-p4-injection-guide.html']: print(f, (dist / f).stat().st_size, '' if local_ok else '(libraries from the CDN: run npm ci for local copies)')
